PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE usuarios (email TEXT PRIMARY KEY, admin INTEGER NOT NULL DEFAULT 0, activo INTEGER NOT NULL DEFAULT 1, creado TEXT NOT NULL, ultimo_acceso TEXT);
CREATE TABLE config (clave TEXT PRIMARY KEY, valor TEXT NOT NULL, actualizado TEXT, actualizado_por TEXT);
CREATE TABLE sesiones (token TEXT PRIMARY KEY, email TEXT NOT NULL, creado TEXT NOT NULL, expira INTEGER NOT NULL);
CREATE TABLE intentos (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT, ip TEXT, ts INTEGER NOT NULL);
CREATE TABLE cargas (id TEXT PRIMARY KEY, creado TEXT NOT NULL, creado_por TEXT NOT NULL, corte REAL NOT NULL, periodo TEXT, responsable TEXT, nps TEXT, glpi_nombre TEXT, tip_nombre TEXT, resumen TEXT, partes INTEGER NOT NULL, bytes INTEGER NOT NULL, meses TEXT, inicio REAL, fin REAL);
CREATE TABLE carga_partes (carga_id TEXT NOT NULL, idx INTEGER NOT NULL, datos BLOB NOT NULL, PRIMARY KEY (carga_id, idx));
CREATE TABLE revisiones (carga_id TEXT NOT NULL, clave TEXT NOT NULL, tickets TEXT NOT NULL, procede TEXT NOT NULL, por TEXT NOT NULL, fecha TEXT NOT NULL, heredada INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (carga_id, clave));
DELETE FROM sqlite_sequence;
CREATE INDEX intentos_ts ON intentos (ts);
